fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        let v1 = vals_1[i];
        let v2 = vals_2[i];

        // According to the problem, at least one of c1 or c2 must be true
        // so no need to handle the case where both are false.

        let val = match (c1, c2) {
            (true, true) => (v1 + v2) / 2,
            (true, false) => v1,
            (false, true) => v2,
            (false, false) => unreachable!("At least one condition must be true"),
        };

        avgs.push(val);
    }
}